    private void TCariKeyPressed(java.awt.event.KeyEvent evt) {//GEN-FIRST:event_TCariKeyPressed
        if(evt.getKeyCode()==KeyEvent.VK_ENTER){
            TampilkanData();
        }else if(evt.getKeyCode()==KeyEvent.VK_PAGE_DOWN){
            BtnCari.requestFocus();
        }else if(evt.getKeyCode()==KeyEvent.VK_PAGE_UP){
            BtnKeluar.requestFocus();
        }else if(evt.getKeyCode()==KeyEvent.VK_UP){
            switch (TabRawat.getSelectedIndex()) {
                case 0:
                    if(TabRawatTindakanDokter.getSelectedIndex()==0){
                        tbTindakan.requestFocus();
                    }else if(TabRawatTindakanDokter.getSelectedIndex()==1){
                        tbRawatDr.requestFocus();
                    }
                    break;
                /*case 1:
                    if(TabRawatTindakanPetugas.getSelectedIndex()==0){
                        tbTindakan2.requestFocus();
                    }else if(TabRawatTindakanPetugas.getSelectedIndex()==1){
                        tbRawatPr.requestFocus();
                    }
                    break;*/
                case 1:
                    if(TabRawatTindakanDokterPetugas.getSelectedIndex()==0){
                        tbTindakan3.requestFocus();
                    }else if(TabRawatTindakanDokterPetugas.getSelectedIndex()==1){
                        tbRawatDrPr.requestFocus();
                    }
                    break;
                case 2:
                    tbPemeriksaan.requestFocus();
                    break;
                case 3:
                    if(TabRawat1.getSelectedIndex()==0){
                        tampilobat();
                    }else if(TabRawat1.getSelectedIndex()==1){
                        if(tbObatResepRacikan.getRowCount()!=0){
                            if(tbObatResepRacikan.getSelectedRow()!= -1){
                                if(tbObatResepRacikan.getValueAt(tbObatResepRacikan.getSelectedRow(),0).toString().equals("")||
                                    tbObatResepRacikan.getValueAt(tbObatResepRacikan.getSelectedRow(),1).toString().equals("")||
                                    tbObatResepRacikan.getValueAt(tbObatResepRacikan.getSelectedRow(),2).toString().equals("")||
                                    tbObatResepRacikan.getValueAt(tbObatResepRacikan.getSelectedRow(),3).toString().equals("")||
                                    tbObatResepRacikan.getValueAt(tbObatResepRacikan.getSelectedRow(),4).toString().equals("")||
                                    tbObatResepRacikan.getValueAt(tbObatResepRacikan.getSelectedRow(),5).toString().equals("")||
                                    tbObatResepRacikan.getValueAt(tbObatResepRacikan.getSelectedRow(),6).toString().equals("")){
                                    JOptionPane.showMessageDialog(null,"Silahkan lengkapi data racikan..!!");
                                }else{
                                    tampildetailracikanresep();
                                }
                            }else{
                                JOptionPane.showMessageDialog(null,"Silahkan pilih racikan..!!");
                            }
                        }else{
                            JOptionPane.showMessageDialog(null,"Silahkan masukkan racikan..!!");
                        }
                    }else if(TabRawat1.getSelectedIndex()==2){
                        tampil();
                    }
                    break;
                case 4:
                    tbPemeriksaanObstetri.requestFocus();
                    break;
                case 5:
                    tbPemeriksaanGinekologi.requestFocus();
                    break;
                default:
                    break;
            }
        }
}//GEN-LAST:event_TCariKeyPressed

