    private void PrintLayananKFRDokterActionPerformed(java.awt.event.ActionEvent evt) {//GEN-FIRST:event_PrintLayananKFRDokterActionPerformed
        if(tbPemeriksaan.getSelectedRow() > -1){
            if(TPoliklinik.getText().equals("Poliklinik Rehab Medik")||TPoliklinik.getText().equals("Poliklinik Rehab Medis")||TPoliklinik.getText().equals("Poliklinik Fisioterapi")){
                String noRawat = tbPemeriksaan.getValueAt(tbPemeriksaan.getSelectedRow(), 1).toString();
                String nipdokter = tbPemeriksaan.getValueAt(tbPemeriksaan.getSelectedRow(), 23).toString();
                String tglPerawatan = tbPemeriksaan.getValueAt(tbPemeriksaan.getSelectedRow(), 4).toString();
                String jamRawat = tbPemeriksaan.getValueAt(tbPemeriksaan.getSelectedRow(), 5).toString();

                int countPetugas = Sequel.cariInteger("select count(*) from dokter where kd_dokter=?", nipdokter);
                if(countPetugas < 1){
                    JOptionPane.showMessageDialog(null, "Bukan SOAP Dokter!");
                    return;
                }else{
                    Map<String, Object> param = new HashMap<>();
                    param.put("namars", akses.getnamars());
                    param.put("alamatrs", akses.getalamatrs());
                    param.put("kotars", akses.getkabupatenrs());
                    param.put("propinsirs", akses.getpropinsirs());
                    param.put("kontakrs", akses.getkontakrs());
                    param.put("emailrs", akses.getemailrs());
                    param.put("logo", Sequel.cariGambar("select setting.logo from setting"));

                    Valid.MyReportqry("rptCetakLayananKFRdokter.jasper", "report",
                        "::[ Lembar Formulir Layanan Rawat Jalan Kedokteran Fisik & Rehabilitasi ]::",
                        "select reg_periksa.no_rawat, pasien.no_rkm_medis, " +
                        "pasien.nm_pasien, if(pasien.jk='L','Laki-Laki','Perempuan') as jk, " +
                        "pasien.tgl_lahir, " +
                        "pemeriksaan_ralan.tgl_perawatan as tanggal, " +
                        "pemeriksaan_ralan.nip as kd_dokter, " +
                        "dokter.nm_dokter, " +
                        "pemeriksaan_ralan.keluhan as subject, " +
                        "pemeriksaan_ralan.pemeriksaan as object, " +
                        "pemeriksaan_ralan.penilaian as assesment, " +
                        "pemeriksaan_ralan.instruksi as plan, " +
                        "pemeriksaan_ralan.rtl, " +
                        "kelurahan.nm_kel, " +
                        "kecamatan.nm_kec, " +
                        "kabupaten.nm_kab, " +
                        "propinsi.nm_prop, " +
                        "poliklinik.nm_poli, " +
                        "pasien.alamat " +
                        "from reg_periksa " +
                        "inner join pasien on reg_periksa.no_rkm_medis=pasien.no_rkm_medis " +
                        "inner join kelurahan on kelurahan.kd_kel=pasien.kd_kel " +
                        "inner join kecamatan on kecamatan.kd_kec=pasien.kd_kec " +
                        "inner join kabupaten on kabupaten.kd_kab=pasien.kd_kab " +
                        "inner join propinsi on propinsi.kd_prop=pasien.kd_prop " +
                        "inner join poliklinik on reg_periksa.kd_poli=poliklinik.kd_poli " +
                        "inner join pemeriksaan_ralan on reg_periksa.no_rawat=pemeriksaan_ralan.no_rawat " +
                        "inner join dokter on pemeriksaan_ralan.nip=dokter.kd_dokter " +
                        "where pemeriksaan_ralan.no_rawat='" + noRawat + "' and pemeriksaan_ralan.tgl_perawatan='" + tglPerawatan + "' and pemeriksaan_ralan.jam_rawat='" + jamRawat + "'", param);
                }
            }else{
                JOptionPane.showMessageDialog(null, "Bukan SOAP Rehab Medik");
            }
        }else{
            JOptionPane.showMessageDialog(null, "Pilih Data Terlebih Dahulu!");
        }
    }//GEN-LAST:event_PrintLayananKFRDokterActionPerformed

    private void PrintLayananKFRTerapisActionPerformed(java.awt.event.ActionEvent evt) {//GEN-FIRST:event_PrintLayananKFRTerapisActionPerformed
        if(tbPemeriksaan.getSelectedRow()>-1){
            if(TPoliklinik.getText().equals("Poliklinik Rehab Medik")||TPoliklinik.getText().equals("Poliklinik Rehab Medis")||TPoliklinik.getText().equals("Poliklinik Fisioterapi")){
                String noRawat = tbPemeriksaan.getValueAt(tbPemeriksaan.getSelectedRow(), 1).toString();
                String nippetugas = tbPemeriksaan.getValueAt(tbPemeriksaan.getSelectedRow(), 23).toString();
                String tglPerawatan = tbPemeriksaan.getValueAt(tbPemeriksaan.getSelectedRow(), 4).toString();
                String jamRawat = tbPemeriksaan.getValueAt(tbPemeriksaan.getSelectedRow(), 5).toString();

                // Validasi apakah petugas valid
                int countPetugas = Sequel.cariInteger("select count(*) from petugas where nip=?", nippetugas);
                if(countPetugas < 1){
                    JOptionPane.showMessageDialog(null, "Bukan SOAP Petugas!");
                    return;
                }else{
                    // Lanjutkan ke proses cetak
                    Map<String, Object> param = new HashMap<>();
                    param.put("namars",akses.getnamars());
                    param.put("alamatrs",akses.getalamatrs());
                    param.put("kotars",akses.getkabupatenrs());
                    param.put("propinsirs",akses.getpropinsirs());
                    param.put("kontakrs",akses.getkontakrs());
                    param.put("emailrs",akses.getemailrs());
                    param.put("logo",Sequel.cariGambar("select setting.logo from setting"));

                    // Finger print untuk tanda tangan elektronik dokter
                    String nmdokterttd = Sequel.cariIsi("select dokter.nm_dokter from dokter inner join reg_periksa on dokter.kd_dokter=reg_periksa.kd_dokter where reg_periksa.no_rawat=?", noRawat);
                    String iddokterttd = Sequel.cariIsi("select reg_periksa.kd_dokter from reg_periksa where reg_periksa.no_rawat=?", noRawat);

                    // Jika dokter tidak ditemukan, gunakan data dari tabel pemeriksaan
                    if (nmdokterttd == null || nmdokterttd.trim().equals("")) {
                        nmdokterttd = tbPemeriksaan.getValueAt(tbPemeriksaan.getSelectedRow(), 24).toString();
                    }
                    if (iddokterttd == null || iddokterttd.trim().equals("")) {
                        iddokterttd = tbPemeriksaan.getValueAt(tbPemeriksaan.getSelectedRow(), 23).toString();
                    }

                    String finger1 =
                    "Dikeluarkan di " + akses.getnamars() +
                    ", Kabupaten/Kota " + akses.getkabupatenrs() + "\n" +
                    "Ditandatangani secara elektronik oleh\n" +
                    nmdokterttd + "\n" +
                    "ID " + iddokterttd + "\n" +
                    Valid.SetTgl3(tbPemeriksaan.getValueAt(tbPemeriksaan.getSelectedRow(), 4).toString());
                    param.put("finger1", finger1);

                    // Finger print untuk tanda tangan elektronik terapis
                    String nmterapisttd = Sequel.cariIsi("select petugas.nama from petugas where petugas.nip=?", nippetugas);
                    String idterapisttd = nippetugas;

                    // Jika terapis tidak ditemukan, gunakan data dari tabel pemeriksaan
                    if (nmterapisttd == null || nmterapisttd.trim().equals("")) {
                        nmterapisttd = tbPemeriksaan.getValueAt(tbPemeriksaan.getSelectedRow(), 24).toString();
                    }
                    if (idterapisttd == null || idterapisttd.trim().equals("")) {
                        idterapisttd = tbPemeriksaan.getValueAt(tbPemeriksaan.getSelectedRow(), 23).toString();
                    }

                    String finger2 =
                    "Dikeluarkan di " + akses.getnamars() +
                    ", Kabupaten/Kota " + akses.getkabupatenrs() + "\n" +
                    "Ditandatangani secara elektronik oleh\n" +
                    nmterapisttd + "\n" +
                    "ID " + idterapisttd + "\n" +
                    Valid.SetTgl3(tbPemeriksaan.getValueAt(tbPemeriksaan.getSelectedRow(), 4).toString());
                    param.put("finger2", finger2);

                    Valid.MyReportqry("rptFormulirLayananKFRTerapis.jasper","report","::[ Formulir Layanan KFR Terapis ]::",
                        "select reg_periksa.no_rawat,pasien.no_rkm_medis,pasien.nm_pasien,"+
                        "concat(reg_periksa.umurdaftar,' ',reg_periksa.sttsumur) as umur,"+
                        "if(pasien.jk='L','Laki-Laki','Perempuan') as jk,pasien.tgl_lahir,"+
                        "pemeriksaan_ralan.tgl_perawatan as tanggal,reg_periksa.kd_dokter,dokter.nm_dokter,"+
                        "pemeriksaan_ralan.nip as kd_terapis,petugas.nama as nm_terapis,"+
                        "pemeriksaan_ralan.keluhan as subject,pemeriksaan_ralan.pemeriksaan as object,"+
                        "pemeriksaan_ralan.penilaian as assesment,pemeriksaan_ralan.instruksi as program,"+
                        "pasien.alamat,kelurahan.nm_kel,kecamatan.nm_kec,kabupaten.nm_kab,propinsi.nm_prop,"+
                        "poliklinik.nm_poli,now() as sekarang "+
                        "from pemeriksaan_ralan "+
                        "inner join reg_periksa on pemeriksaan_ralan.no_rawat=reg_periksa.no_rawat "+
                        "inner join pasien on reg_periksa.no_rkm_medis=pasien.no_rkm_medis "+
                        "inner join dokter on reg_periksa.kd_dokter=dokter.kd_dokter "+
                        "inner join petugas on pemeriksaan_ralan.nip=petugas.nip "+
                        "inner join kelurahan on pasien.kd_kel=kelurahan.kd_kel "+
                        "inner join kecamatan on pasien.kd_kec=kecamatan.kd_kec "+
                        "inner join kabupaten on pasien.kd_kab=kabupaten.kd_kab "+
                        "inner join propinsi on pasien.kd_prop=propinsi.kd_prop "+
                        "inner join poliklinik on reg_periksa.kd_poli=poliklinik.kd_poli "+
                        "where pemeriksaan_ralan.no_rawat='"+noRawat+"' and pemeriksaan_ralan.nip='"+nippetugas+"' and pemeriksaan_ralan.tgl_perawatan='"+tglPerawatan+"' and pemeriksaan_ralan.jam_rawat='"+jamRawat+"' "+
                        "order by pemeriksaan_ralan.tgl_perawatan",param);
                }
            }else{
                JOptionPane.showMessageDialog(null, "Bukan SOAP Rehab Medik");
            }
        }else{
            JOptionPane.showMessageDialog(null, "Pilih Data Terlebih Dahulu!");
        }
    }//GEN-LAST:event_PrintLayananKFRTerapisActionPerformed

    
