        //poliklinik=Sequel.cariIsi("select poliklinik.nm_poli from poliklinik inner join reg_periksa on reg_periksa.kd_poli=poliklinik.kd_poli where reg_periksa.no_rawat='"+TNoRw.getText()+"'");
        //Sequel.cariIsiAngka("select count(penilaian_medis_igd.no_rawat) from penilaian_medis_igd inner join reg_periksa on reg_periksa.no_rawat=penilaian_medis_igd.no_rawat where penilaian_medis_igd.tanggal between '"+Valid.SetTgl(DTPCari3.getSelectedItem().toString()+"")+"' and '"+Valid.SetTgl(DTPCari2.getSelectedItem().toString()+"")+"' and reg_periksa.no_rkm_medis='"+TNoRM.getText()+"'");
        cekasesmenmedis=Sequel.cariInteger("select count(penilaian_medis_igd.no_rawat) from penilaian_medis_igd inner join reg_periksa on reg_periksa.no_rawat=penilaian_medis_igd.no_rawat where penilaian_medis_igd.tanggal between '"+Valid.SetTgl(DTPCari3.getSelectedItem()+"")+"' and '"+Valid.SetTgl(DTPCari2.getSelectedItem()+"")+"' and reg_periksa.no_rkm_medis='"+TNoRM.getText()+"'");
