        asesmenkandungan=Sequel.cariInteger("select count(penilaian_medis_ralan_kandungan.no_rawat) from penilaian_medis_ralan_kandungan inner join reg_periksa on reg_periksa.no_rawat=penilaian_medis_ralan_kandungan.no_rawat where penilaian_medis_ralan_kandungan.tanggal between '"+Valid.SetTgl(DTPCari3.getSelectedItem()+"")+"' and '"+Valid.SetTgl(DTPCari2.getSelectedItem()+"")+"' and reg_periksa.no_rkm_medis='"+TNoRM.getText()+"'");
        asesmenmata=Sequel.cariInteger("select count(penilaian_medis_ralan_mata.no_rawat) from penilaian_medis_ralan_mata inner join reg_periksa on reg_periksa.no_rawat=penilaian_medis_ralan_mata.no_rawat where penilaian_medis_ralan_mata.tanggal between '"+Valid.SetTgl(DTPCari3.getSelectedItem()+"")+"' and '"+Valid.SetTgl(DTPCari2.getSelectedItem()+"")+"' and reg_periksa.no_rkm_medis='"+TNoRM.getText()+"'");
